for(const [locale,text] of Object.entries({"es":"Se utilizan los períodos declarados hasta la fecha prevista de jubilación. Los solapamientos indicados se descuentan; si no los indicas, el escenario supone que no existen. Los períodos recientes corresponden a los 15 años anteriores a esa fecha; otras situaciones de referencia requieren revisión.","en":"Declared periods refer to the planned retirement date. Entered overlaps are deducted; otherwise the scenario assumes none. Recent periods fall in the 15 years before that date; alternative reference windows require review.","uk":"Указані періоди стосуються запланованої дати виходу на пенсію. Зазначені збіги віднімаються; без них сценарій припускає їх відсутність. Недавні періоди належать до 15 років перед цією датою; інший відлік потребує перевірки.","ru":"Указанные периоды относятся к планируемой дате выхода на пенсию. Указанные совпадения вычитаются; иначе предполагается их отсутствие. Недавние периоды относятся к 15 годам перед этой датой; другой отсчёт требует проверки."}))translations[locale].periodAssumption=text;

for(const [locale,labels] of Object.entries({"es":["Años totales cotizados en España hasta la jubilación prevista","Años totales cotizados en Ucrania hasta la jubilación prevista"],"uk":["Загальний стаж в Іспанії до запланованого виходу на пенсію","Загальний стаж в Україні до запланованого виходу на пенсію"],"en":["Total contribution years in Spain by planned retirement","Total contribution years in Ukraine by planned retirement"],"ru":["Общий стаж в Испании к планируемому выходу на пенсию","Общий стаж в Украине к планируемому выходу на пенсию"]})){translations[locale].spainYearsLabel=labels[0];translations[locale].ukraineYearsLabel=labels[1];}
